1	/**
2	 * Pure account-state wording shared by the Account drawer, the header status
3	 * note and the empty inbox line. Everything derives from `AccountStatus`
4	 * (connection, sync state and error, initial sync, cached count); nothing here
5	 * invents a state, and pending, failed and unknown stay distinct.
6	 *
7	 * Actions are never gated by the connection (a Gmail command with an expired
8	 * sign-in still runs and fails at the provider), so no text here says actions
9	 * are off. The one standing fact worth saying is about reading: cached mail
10	 * stays readable.
11	 */
12	import type { AccountStatus, MailError } from './ipc/client';
13	
14	/** One plain sentence per typed error. */
15	export function describeMailError(error: MailError): string {
16	  switch (error.kind) {
17	    case 'not_configured':
18	      return 'Gmail is not configured on this device.';
19	    case 'auth_required':
20	      return 'Sign-in is required to continue syncing.';
21	    case 'auth_cancelled':
22	      return 'Sign-in was cancelled.';
23	    case 'auth_failed':
24	      return 'Sign-in failed.';
25	    case 'secrets_unavailable':
26	      return 'Secure credential storage is unavailable.';
27	    case 'network_unavailable':
28	      return 'The network is unavailable.';
29	    case 'rate_limited':
30	      return 'The provider is rate limiting; retrying with backoff.';
31	    case 'provider_unavailable':
32	      return 'The mail provider is temporarily unavailable.';
33	    case 'invalid_provider_response':
34	      return 'The provider returned an unexpected response.';
35	    case 'busy':
36	      return 'A sync is already in progress.';
37	    case 'permission_required':
38	      return 'Google did not grant mailbox-action permission; the account remains read-only.';
39	    case 'provider_rejected':
40	      return 'The provider rejected the mailbox action.';
41	    case 'outcome_unknown':
42	      return 'The provider outcome is unknown; review Activity before retrying.';
43	    case 'read_only':
44	      return 'Gmail is read-only; this action is unavailable.';
45	    case 'storage_unavailable':
46	      return 'Local storage is unavailable.';
47	    case 'not_found':
48	      return 'Not found.';
49	    case 'invalid_request':
50	      return 'Invalid request.';
51	    case 'request_id_conflict':
52	      return 'Conflicting request.';
53	    case 'profile_in_use':
54	      return 'The profile is in use by another window.';
55	    default:
56	      return 'Unknown error.';
57	  }
58	}
59	
60	export type AccountNoticeKind =
61	  | 'not_configured' | 'disconnected' | 'auth_required' | 'authenticating'
62	  | 'syncing' | 'offline' | 'sync_failed';
63	export type AccountNoticeAction = 'connect' | 'sync' | 'cancel';
64	
65	/** The header note: terse visible text, the full fact in `title`. */
66	export interface AccountNotice {
67	  kind: AccountNoticeKind;
68	  /** Visible words. */
69	  text: string;
70	  /**
71	   * Self-contained sentence(s): the hover title and the visually hidden text.
72	   * It never contains a ticking count, so it can be announced once.
73	   */
74	  title: string;
75	  action: AccountNoticeAction | null;
76	  actionLabel: string;
77	  tone: 'neutral' | 'warning' | 'danger';
78	}
79	
80	/**
81	 * Short visible cause for a failed sync, so the header says why without a hover.
82	 * A kind with no phrase here gets none: an unknown cause is never relabelled.
83	 */
84	const SYNC_CAUSE_WORDS: Partial<Record<MailError['kind'], string>> = {
85	  network_unavailable: 'no network',
86	  rate_limited: 'rate limited',
87	  provider_unavailable: 'provider unavailable',
88	  storage_unavailable: 'storage unavailable',
89	};
90	
91	/**
92	 * The older read-only hint ("Gmail is read-only · Review access") steps aside
93	 * while any account status note shows (connection or sync): the Account drawer
94	 * covers it, and the header is too narrow for both (DESIGN.md gap 18).
95	 */
96	export function readOnlyHintShown(status: AccountStatus | null, notice: AccountNotice | null): boolean {
97	  return !!status && status.mode === 'gmail' && status.mutationAccess !== 'enabled' && !notice;
98	}
99	
100	/**
101	 * The header note's link. It is dropped while the empty inbox line carries the
102	 * action (one action, one place); a not-configured device gets a single Account
103	 * link because there is nothing to connect with.
104	 */
105	export function headerNoticeAction(
106	  notice: AccountNotice | null,
107	  emptyLineCarriesAction: boolean,
108	): { action: AccountNoticeAction | 'account'; label: string } | null {
109	  if (!notice || emptyLineCarriesAction) return null;
110	  if (notice.action) return { action: notice.action, label: notice.actionLabel };
111	  return notice.kind === 'not_configured' ? { action: 'account', label: 'Account' } : null;
112	}
113	
114	/** Null in fixture mode, without a status, and while connected and idle. */
115	export function accountNotice(status: AccountStatus | null): AccountNotice | null {
116	  if (!status || status.mode !== 'gmail') return null;
117	  const { sync } = status;
118	  const cached = sync.cachedConversations;
119	  switch (status.connection) {
120	    case 'not_configured':
121	      return {
122	        kind: 'not_configured', text: 'Gmail not configured', action: null, actionLabel: '', tone: 'neutral',
123	        title: 'Gmail is not configured on this device. Connecting is unavailable.',
124	      };
125	    case 'disconnected':
126	      return {
127	        kind: 'disconnected', text: 'Not connected', action: 'connect', actionLabel: 'Connect', tone: 'neutral',
128	        title: cached > 0
129	          ? 'Not connected to Gmail. Cached mail stays readable; new mail will not sync until you connect.'
130	          : 'Not connected to Gmail. Connect to load and sync mail.',
131	      };
132	    case 'auth_required':
133	      return {
134	        kind: 'auth_required', text: 'Sign-in expired', action: 'connect', actionLabel: 'Sign in', tone: 'warning',
135	        title: 'Sign-in expired. Cached mail stays readable; new mail will not sync until you sign in.',
136	      };
137	    case 'authenticating':
138	      return {
139	        kind: 'authenticating', text: 'Finish sign-in in your browser', action: 'cancel', actionLabel: 'Cancel', tone: 'neutral',
140	        title: 'Gmail sign-in is waiting for your browser. Cancel stops it.',
141	      };
142	    case 'connected':
143	      break;
144	  }
145	  if (sync.state === 'error') {
146	    const firstSync = sync.initialSyncComplete ? '' : ` · ${cached} cached`;
147	    const cause = sync.error ? `${describeMailError(sync.error)} ` : '';
148	    const causeWords = sync.error ? SYNC_CAUSE_WORDS[sync.error.kind] : undefined;
149	    const text = `Sync failed${causeWords ? ` · ${causeWords}` : ''}${firstSync}`;
150	    const title = `Sync failed. ${cause}Cached mail stays readable; new mail has not synced.`;
151	    // 'offline' stays the internal kind for a network cause; the visible words are always "Sync failed".
152	    const kind = sync.error?.kind === 'network_unavailable' ? 'offline' : 'sync_failed';
153	    return { kind, text, action: 'sync', actionLabel: 'Retry', tone: 'danger', title };
154	  }
155	  if (sync.state === 'syncing') {
156	    return sync.initialSyncComplete
157	      ? { kind: 'syncing', text: 'Syncing…', title: 'Syncing mail. Cached mail stays readable.', action: null, actionLabel: '', tone: 'neutral' }
158	      : { kind: 'syncing', text: `Syncing first mail · ${cached} cached`, title: 'Syncing first mail. Cached mail stays readable.', action: null, actionLabel: '', tone: 'neutral' };
159	  }
160	  return null;
161	}
162	
163	export const INBOX_EMPTY_RECOVERABLE = 'No conversations are currently in the inbox. Archived conversations stay recoverable from Activity.';
164	/** Gmail without mailbox actions: Activity offers no Mark not done there, so it is not promised. */
165	export const INBOX_EMPTY_READ_ONLY = 'No conversations in the cached inbox.';
166	
167	export type InboxEmptyKind =
168	  | 'not_configured' | 'disconnected' | 'auth_required' | 'authenticating'
169	  | 'syncing' | 'sync_error' | 'sync_unfinished' | 'empty';
170	export type InboxEmptyAction = 'connect' | 'sync' | 'cancel' | 'account';
171	
172	/** What Connect does, said once, only where Connect really is the action. */
173	export const FIRST_RUN_HINT = 'Opens Google sign-in in your browser. Starts read-only.';
174	
175	export interface InboxEmpty {
176	  kind: InboxEmptyKind;
177	  text: string;
178	  /** One quieter line under the sentence; absent in most states. */
179	  hint?: string;
180	  action: InboxEmptyAction | null;
181	  actionLabel: string;
182	}
183	
184	/**
185	 * What a plain, zero-row Gmail inbox really means. Null outside Gmail mode (the
186	 * caller keeps the fixture sentence). Only a connected, fully synced account
187	 * gets the real "empty" text.
188	 */
189	export function inboxEmptyState(status: AccountStatus | null): InboxEmpty | null {
190	  if (!status || status.mode !== 'gmail') return null;
191	  const { sync } = status;
192	  switch (status.connection) {
193	    case 'not_configured':
194	      return { kind: 'not_configured', text: 'Gmail is not configured on this device.', action: 'account', actionLabel: 'Account' };
195	    case 'disconnected':
196	      return { kind: 'disconnected', text: 'Not connected.', hint: FIRST_RUN_HINT, action: 'connect', actionLabel: 'Connect Gmail' };
197	    case 'auth_required':
198	      return { kind: 'auth_required', text: 'Sign-in expired.', action: 'connect', actionLabel: 'Sign in again' };
199	    case 'authenticating':
200	      return { kind: 'authenticating', text: 'Finish sign-in in your browser.', action: 'cancel', actionLabel: 'Cancel' };
201	    case 'connected':
202	      break;
203	  }
204	  if (sync.state === 'error') {
205	    const cause = sync.error ? describeMailError(sync.error) : 'Unknown error.';
206	    return { kind: 'sync_error', text: `Sync failed: ${cause}`, action: 'sync', actionLabel: 'Retry' };
207	  }
208	  if (!sync.initialSyncComplete) {
209	    return sync.state === 'syncing'
210	      ? { kind: 'syncing', text: `Syncing first mail… ${sync.cachedConversations} cached.`, action: null, actionLabel: '' }
211	      : { kind: 'sync_unfinished', text: 'Initial sync has not finished.', action: 'sync', actionLabel: 'Sync now' };
212	  }
213	  return {
214	    kind: 'empty',
215	    text: status.mutationAccess === 'enabled' ? INBOX_EMPTY_RECOVERABLE : INBOX_EMPTY_READ_ONLY,
216	    action: null,
217	    actionLabel: '',
218	  };
219	}
