:where(.app-main) :is(strong, b) {
  font-weight: var(--weight-strong);
}

/*
 * Split header (DESIGN.md "Split Tabs"): one borderless 78px strip in the list
 * column. Hamburger centered 23px into the pane, tabs on the 50px content
 * inset and vertically centered ~42px down, right glyphs on the 32px action
 * pitch with the last glyph centered 32px from the pane edge. Extra rows
 * (split editor, split error) wrap below the tab line.
 */
.app-header {
  /* The tab column never drops below this: the trail's notes give up width first (DESIGN.md gap 18).
     About "Inbox 18", the 18px gap and the "Unread only" chip. */
  --header-tabs-floor: 10rem;
  display: grid;
  grid-template-columns: 50px minmax(min(var(--header-tabs-floor), 100%), 1fr) minmax(0, auto);
  grid-template-rows: minmax(calc(var(--split-header-height) - 6px), auto);
  align-items: center;
  padding: 6px 16px 0 0;
  background: var(--surface);
}

.app-header > .header-row {
  grid-column: 1 / -1;
  padding-left: 50px;
}

.header-alert {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  margin: 0 0 6px;
  font-size: var(--type-body);
}

.header-menu {
  justify-self: start;
  margin-left: 7px;
}

.header-tabs {
  display: flex;
  align-items: baseline;
  gap: 18px;
  min-width: 0;
  overflow: hidden;
  /* Room for the focus ring of the first tab inside the clipped line. */
  padding: 4px 4px 4px 0;
  margin: -4px 0;
}

.app-title,
.split-tab {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  line-height: var(--leading-headline);
}

.app-title {
  margin: 0;
  min-width: 0;
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}

.app-title-account {
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.split-nav {
  display: flex;
  align-items: baseline;
  gap: 18px;
  min-width: 0;
}

.split-tab {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 2px;
  color: var(--text-tertiary);
  white-space: nowrap;
  cursor: pointer;
}

.split-tab:hover,
.split-tab[aria-current='page'] {
  color: var(--text-primary);
}

.split-tab:focus-visible {
  outline-offset: 2px;
}

.split-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.split-count {
  flex: 0 0 auto;
  font-size: var(--type-count);
  line-height: 1;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

/* Active list filter, in words beside the tabs. */
.header-filter {
  flex: 0 0 auto;
  font-size: var(--type-body);
  color: var(--text-secondary);
  white-space: nowrap;
}

.header-trail {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
}

/* Compact one-line notes; they give up width before the glyphs do. */
.header-note {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0 12px 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

/* Shrink order when the trail is tight: Preview tag first, read-only hint next, the account status last.
   The glyphs (flex: 0 0 auto) never shrink, and the tab column keeps its floor. */
.preview-tag {
  flex-shrink: 4;
  /* Never fully hidden: "Preview ·…" stays readable, and the full disclosure is its title. */
  min-width: 5.5rem;
  color: var(--warning);
}

.access-hint {
  flex-shrink: 2;
}

.header-note.account-status-note {
  flex-shrink: 1;
  display: flex;
  align-items: baseline;
}

/* Only the words ellipsize; the action link never clips (the empty line and the drawer are not always in view). */
.account-status-note .note-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-status-note .note-sep {
  flex: none;
  padding: 0 0.35em;
}

.account-status-note .header-link {
  flex: none;
}

/* Account status note (connection or sync). Words always carry the status; the tint only echoes them. */
.header-note.tone-warning {
  color: var(--warning);
}

.header-note.tone-danger {
  color: var(--danger);
}

/* Armed g-chord: a quiet pending hint at the trail's leading edge. */
.chord-hint {
  flex: 0 0 auto;
  margin: 0 12px 0 0;
  font-size: var(--type-body);
  color: var(--text-secondary);
  white-space: nowrap;
}

.chord-hint:empty {
  display: none;
}

.header-link {
  padding: 0 2px;
}

/* A link-style action inside an in-flow line (the empty inbox line). */
.inline-action {
  margin-left: 6px;
  padding: 0 2px;
  background: transparent;
  border: 0;
  color: var(--text-primary);
  font: inherit;
  font-weight: var(--weight-strong);
  text-decoration: underline;
  cursor: pointer;
}

.inline-action:hover {
  background: transparent;
}

/* A ghost text button inside a utility drawer (drawers default to the bordered chip). */
.drawer-ghost {
  padding: 0 0 6px;
}

/* Loading and empty list states, and Load more, on the content inset. */
.list-state {
  margin: 0;
  padding: 10px 24px 10px 50px;
  max-width: calc(75ch + 74px);
  color: var(--text-secondary);
}

.list-state:focus {
  outline: none;
}

/* The one quieter line under an empty-state sentence (what Connect does). */
.list-state-hint {
  display: block;
  margin-top: 4px;
  color: var(--text-secondary);
}

.list-state:focus-visible {
  outline: 2px solid var(--focus-accent);
  outline-offset: -2px;
}

.list-more {
.contact-line > :first-child {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* Name: centered on the tab line within a header-height block; a long name
   wraps around that center before it pushes the email down. */
.contact-column .contact-line-name,
.contact-column .contact-unknown {
  min-height: var(--split-header-height);
  padding-top: 6px;
}

.contact-column .contact-unknown {
  display: flex;
  align-items: center;
}

/* Email: the 36px line after the header block, i.e. the first list line. */
.contact-column .contact-line-mailbox {
  min-height: 36px;
}

/* Headline: the contact name is the pane's one large line. */
.contact-name {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  line-height: var(--leading-headline);
  color: var(--text-primary);
}

.contact-search {
  background: none;
  border: 0;
  padding: 0;
  text-align: left;
  overflow-wrap: anywhere;
  cursor: pointer;
}
.contact-search:hover { text-decoration: underline; }

/* Title: the email is Paper White semibold (DESIGN.md contact-pane). */
.contact-mailbox {
  color: var(--text-primary);
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
}

.contact-unknown {
  color: var(--text-secondary);
  font-size: var(--type-body);
  margin: 0;
}

/* Mail section: a Title label with a Graphite glyph, then plain Ash text
   rows (no chips) at a 24px pitch, one line each with an ellipsis. */
.contact-recent {
  margin-top: 0;
}

.contact-recent h3 {
}

/* Ash facts: coverage, the scope disclosure and the disconnect warning. */
.account-note {
  margin: 0;
  color: var(--text-secondary);
}

.account-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.account-confirm {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}

.account-primary {
  font-weight: var(--weight-strong);
}

/* The two answers to "Disconnect?": Keep account is the default (Title weight, Focus Stone fill, the focus lands
   on it); Disconnect is the quiet one. No coral: nothing has failed, and coral is reserved for failures. */
.account-confirm .account-primary {
  background: var(--focus-fill);
}

.account-confirm .account-destructive {
  background: transparent;
  border-color: transparent;
  color: var(--text-secondary);
}

.account-confirm .account-destructive:not(:disabled):hover {
  background: var(--surface-raised);
  color: var(--text-primary);
}

/* Provider mail (catalog -> page -> reader): list-row look, no cards or borders. */
.provider-destinations {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  min-width: 0;
  font-size: var(--type-body);
}

